import type { TFunction } from 'i18next'
import type { AIApprovalPreview } from '@/api'

// Matches exact 24-hex-char platform resource IDs generated by internal/id/id.go (<prefix>_[0-9a-f]{24}).
const OPAQUE_RESOURCE_ID_PATTERN = /^[a-z]{2,8}_[0-9a-f]{24}$/i

// Matches static snake_case resource-type or domain tokens emitted in ApprovalPreview.TargetResource
// by backend handlers when no concrete human instance locator is set.
const GENERIC_RESOURCE_TYPE_TOKENS = new Set([
  'admin',
  'ai_model',
  'ai_provider',
  'app_template',
  'application',
  'applications',
  'artifact_registry',
  'auth_policy',
  'billing',
  'billing_rate_rules',
  'billing_transfer',
  'build',
  'build_environment',
  'build_environment_config',
  'build_run',
  'build_variable_set',
  'cluster_egress_exception',
  'config_set',
  'data_retention',
  'delivery',
  'deployment_target',
  'deployment_targets',
  'gateway_route',
  'git_account',
  'git_provider',
  'global_notification_channel',
  'global_notification_rule',
  'hook_config',
  'inbox_action_request',
  'inbox_message',
  'k8s_resource',
  'network',
  'network_egress_exception',
  'network_policy',
  'network_service_share',
  'network_share',
  'notification_channel',
  'notification_delivery',
  'notification_preferences',
  'notification_rule',
  'notification_template',
  'observability_source',
  'oidc_provider',
  'ops',
  'personal_notification_channel',
  'platform_app_template',
  'platform_mail',
  'platform_mail_settings',
  'project',
  'project_hook',
  'project_member',
  'project_network_policy',
  'project_notification_channel',
  'project_notification_rule',
  'project_topology_edge',
  'project_volume',
  'registry_credential',
  'release',
  'repository_binding',
  'runtime',
  'runtime_cluster',
  'runtime_config_set',
  'runtime_resource',
  'service_binding',
  'system_component',
  'system_configs',
  'user',
  'user_wallet',
  'volume',
  'volume_export',
  'volume_transfer',
  'wallet',
  'workspace',
])

export function isOpaqueResourceId(value: string): boolean {
  return OPAQUE_RESOURCE_ID_PATTERN.test(value.trim())
}

export function formatCompactResourceId(value: string): string {
  const trimmed = value.trim()
  if (!isOpaqueResourceId(trimmed))
    return value
  const underscoreIndex = trimmed.indexOf('_')
  if (underscoreIndex < 0 || trimmed.length <= underscoreIndex + 10)
    return trimmed
  const prefix = trimmed.slice(0, underscoreIndex + 5)
  const suffix = trimmed.slice(-5)
  return `${prefix}…${suffix}`
}

export function isGenericResourceTypeToken(value: string): boolean {
  const trimmed = value.trim().toLowerCase()
  return GENERIC_RESOURCE_TYPE_TOKENS.has(trimmed)
}

export function resolveApprovalFieldLabel(t: TFunction, rawKey: string): string {
  const normalized = rawKey.startsWith('body.') ? rawKey.slice(5) : rawKey
  switch (normalized) {
    case 'project':
    case 'projectId':
      return t('aiAssistant.tools.resources.project')
    case 'target':
    case 'targetId':
    case 'deploymentTarget':
    case 'deploymentTargetId':
      return t('aiAssistant.tools.resources.deploymentTarget')
    case 'cluster':
    case 'clusterId':
      return t('aiAssistant.tools.resources.runtimeCluster')
    case 'template':
    case 'templateId':
      return t('aiAssistant.tools.resources.appTemplate')
    case 'user':
    case 'userId':
      return t('aiAssistant.tools.resources.user')
    case 'application':
    case 'applicationId':
    case 'applicationName':
      return t('aiAssistant.approval.fields.application')
    case 'stage':
      return t('aiAssistant.approval.fields.stage')
    case 'name':
    case 'deploymentName':
      return t('aiAssistant.approval.fields.name')
    case 'identifier':
    case 'applicationIdentifier':
      return t('aiAssistant.approval.fields.identifier')
    case 'sourceType':
      return t('aiAssistant.approval.fields.sourceType')
    case 'imageRef':
      return t('aiAssistant.approval.fields.imageRef')
    case 'repositoryBinding':
    case 'repositoryBindingId':
      return t('aiAssistant.approval.fields.repositoryBinding')
    case 'dockerfilePath':
      return t('aiAssistant.approval.fields.dockerfilePath')
    case 'buildContext':
      return t('aiAssistant.approval.fields.buildContext')
    case 'buildDirectory':
      return t('aiAssistant.approval.fields.buildDirectory')
    case 'buildTemplate':
    case 'buildTemplateId':
      return t('aiAssistant.approval.fields.buildTemplate')
    case 'branchPattern':
      return t('aiAssistant.approval.fields.branchPattern')
    case 'tagPattern':
      return t('aiAssistant.approval.fields.tagPattern')
    case 'autoDeploy':
      return t('aiAssistant.approval.fields.autoDeploy')
    case 'requireApproval':
      return t('aiAssistant.approval.fields.requireApproval')
    case 'targetRegistry':
    case 'targetRegistryId':
      return t('aiAssistant.approval.fields.targetRegistry')
    case 'targetRepository':
      return t('aiAssistant.approval.fields.targetRepository')
    case 'targetTag':
      return t('aiAssistant.approval.fields.targetTag')
    case 'buildVariableSets':
    case 'buildVariableSetIds':
    case 'attachVariableSets':
      return t('aiAssistant.approval.fields.buildVariableSets')
    case 'replicas':
      return t('aiAssistant.approval.fields.replicas')
    case 'cpu':
    case 'buildCpuRequest':
      return t('aiAssistant.approval.fields.cpu')
    case 'memory':
    case 'buildMemoryRequest':
      return t('aiAssistant.approval.fields.memory')
    case 'port':
      return t('aiAssistant.approval.fields.port')
    case 'host':
      return t('aiAssistant.approval.fields.host')
    case 'command':
      return t('aiAssistant.approval.fields.command')
    default:
      return normalized
  }
}

export function resolveApprovalWarningText(t: TFunction, warning: string): string {
  switch (warning) {
    case 'auto_deploy_gated_by_approval':
      return t('aiAssistant.approval.warningCodes.auto_deploy_gated_by_approval')
    case 'pipeline_applies_to_next_build':
      return t('aiAssistant.approval.warningCodes.pipeline_applies_to_next_build')
    default:
      return warning
  }
}

export function formatHumanApprovalValue(t: TFunction, rawValue: string): string {
  if (rawValue === 'true')
    return t('aiAssistant.approval.valueTrue')
  if (rawValue === 'false')
    return t('aiAssistant.approval.valueFalse')
  return formatCompactResourceId(rawValue)
}

function pickCleanLabel(value: unknown): string | undefined {
  if (typeof value !== 'string')
    return undefined
  const trimmed = value.trim()
  if (!trimmed || trimmed.length > 64 || isOpaqueResourceId(trimmed) || isGenericResourceTypeToken(trimmed))
    return undefined
  return trimmed
}

export function extractToolTargetContext(args: Record<string, unknown>, previewTarget?: string): string | undefined {
  const fromPreview = previewTarget?.trim()
  if (fromPreview && !isOpaqueResourceId(fromPreview) && !isGenericResourceTypeToken(fromPreview))
    return fromPreview

  const body = args.body && typeof args.body === 'object' && !Array.isArray(args.body)
    ? args.body as Record<string, unknown>
    : undefined

  const primary = pickCleanLabel(args.application)
    ?? pickCleanLabel(body?.applicationName)
    ?? pickCleanLabel(body?.deploymentName)
    ?? pickCleanLabel(args.name)
    ?? pickCleanLabel(body?.name)
    ?? pickCleanLabel(args.host)
    ?? pickCleanLabel(body?.host)
    ?? pickCleanLabel(args.repositoryBinding)

  const stage = pickCleanLabel(args.stage)
    ?? pickCleanLabel(body?.stage)
    ?? (pickCleanLabel(args.target) && ['dev', 'test', 'staging', 'prod'].includes(String(args.target).trim().toLowerCase()) ? String(args.target).trim() : undefined)

  if (primary && stage && !primary.endsWith(`/${stage}`))
    return `${primary} / ${stage}`
  return primary ?? stage
}

export interface ApprovalScopeSummary {
  project?: { display: string, rawTitle?: string }
  target?: { display: string, rawTitle?: string }
}

export function resolveApprovalScopeSummary(
  args: Record<string, unknown>,
  preview?: AIApprovalPreview,
): ApprovalScopeSummary {
  const body = args.body && typeof args.body === 'object' && !Array.isArray(args.body)
    ? args.body as Record<string, unknown>
    : undefined

  const humanTarget = extractToolTargetContext(args, preview?.targetResource)
  const rawTargetFallback = typeof preview?.targetId === 'string' && preview.targetId.trim()
    ? preview.targetId.trim()
    : undefined
  const target = humanTarget
    ? { display: humanTarget }
    : rawTargetFallback
      ? {
          display: formatCompactResourceId(rawTargetFallback),
          rawTitle: isOpaqueResourceId(rawTargetFallback) ? rawTargetFallback : undefined,
        }
      : undefined

  const argProject = typeof args.project === 'string' && args.project.trim()
    ? args.project.trim()
    : typeof args.projectId === 'string' && args.projectId.trim()
      ? args.projectId.trim()
      : typeof body?.projectId === 'string' && body.projectId.trim()
        ? body.projectId.trim()
        : undefined
  const previewProjectId = typeof preview?.projectId === 'string' && preview.projectId.trim()
    ? preview.projectId.trim()
    : undefined

  const cleanArgProject = argProject && !isOpaqueResourceId(argProject) && !isGenericResourceTypeToken(argProject)
    ? argProject
    : undefined
  const rawProjectId = previewProjectId ?? (argProject && isOpaqueResourceId(argProject) ? argProject : undefined)

  const authoritativeTarget = preview?.targetResource?.trim()
  let project: ApprovalScopeSummary['project']
  if (cleanArgProject) {
    if (!authoritativeTarget || (authoritativeTarget !== cleanArgProject && !authoritativeTarget.startsWith(`${cleanArgProject}/`))) {
      const compactId = rawProjectId && isOpaqueResourceId(rawProjectId) ? formatCompactResourceId(rawProjectId) : undefined
      project = {
        display: compactId ? `${cleanArgProject} (${compactId})` : cleanArgProject,
        rawTitle: rawProjectId,
      }
    }
  }
  else if (rawProjectId) {
    project = {
      display: formatCompactResourceId(rawProjectId),
      rawTitle: isOpaqueResourceId(rawProjectId) ? rawProjectId : undefined,
    }
  }

  return { project, target }
}
